def is_ratelimited(self) -> bool:
    current = time.time()
    if current > self.window + self.per:
        return False
    return self.remaining == 0

def get_delay(self) -> float:
    current = time.time()

    if current > self.window + self.per:
        self.remaining = self.max

    if self.remaining == self.max:
        self.window = current

    if self.remaining == 0:
        return self.per - (current - self.window)

    self.remaining -= 1
    return 0.0

async def identify(self) -> None:
    """Sends the IDENTIFY packet."""
    payload = {
        'op': self.IDENTIFY,
        'd': {
            'token': self.token,
            'properties': {
                'os': sys.platform,
                'browser': 'discord.py',
                'device': 'discord.py',
            },
            'compress': True,
            'large_threshold': 250,
        },
    }

    if self.shard_id is not None and self.shard_count is not None:
        payload['d']['shard'] = [self.shard_id, self.shard_count]

    state = self._connection
    if state._activity is not None or state._status is not None:
        payload['d']['presence'] = {
            'status': state._status,
            'game': state._activity,
            'since': 0,
            'afk': False,
        }

    if state._intents is not None:
        payload['d']['intents'] = state._intents.value

    await self.call_hooks('before_identify', self.shard_id, initial=self._initial_identify)
    await self.send_as_json(payload)
    _log.debug('Shard ID %s has sent the IDENTIFY payload.', self.shard_id)

async def resume(self) -> None:
    """Sends the RESUME packet."""
    payload = {
        'op': self.RESUME,
        'd': {
            'seq': self.sequence,
            'session_id': self.session_id,
            'token': self.token,
        },
    }

    await self.send_as_json(payload)
    _log.debug('Shard ID %s has sent the RESUME payload.', self.shard_id)

async def received_message(self, msg: Any, /) -> None:
    if type(msg) is bytes:
        self._buffer.extend(msg)

        if len(msg) < 4 or msg[-4:] != b'\x00\x00\xff\xff':
            return
        msg = self._zlib.decompress(self._buffer)
        msg = msg.decode('utf-8')
        self._buffer = bytearray()

    self.log_receive(msg)
    msg = utils._from_json(msg)

    _log.debug('For Shard ID %s: WebSocket Event: %s', self.shard_id, msg)
    event = msg.get('t')
    if event:
        self._dispatch('socket_event_type', event)

    op = msg.get('op')
    data = msg.get('d')
    seq = msg.get('s')
    if seq is not None:
        self.sequence = seq

    if self._keep_alive:
        self._keep_alive.tick()

    if op != self.DISPATCH:
        if op == self.RECONNECT:
            # "reconnect" can only be handled by the Client
            # so we terminate our connection and raise an
            # internal exception signalling to reconnect.
            _log.debug('Received RECONNECT opcode.')
            await self.close()
            raise ReconnectWebSocket(self.shard_id)

        if op == self.HEARTBEAT_ACK:
            if self._keep_alive:
                self._keep_alive.ack()
            return

        if op == self.HEARTBEAT:
            if self._keep_alive:
                beat = self._keep_alive.get_payload()
                await self.send_as_json(beat)
            return

        if op == self.HELLO:
            interval = data['heartbeat_interval'] / 1000.0
            self._keep_alive = KeepAliveHandler(ws=self, interval=interval, shard_id=self.shard_id)
            # send a heartbeat immediately
            await self.send_as_json(self._keep_alive.get_payload())
            self._keep_alive.start()
            return

        if op == self.INVALIDATE_SESSION:
            if data is True:
                await self.close()
                raise ReconnectWebSocket(self.shard_id)

            self.sequence = None
            self.session_id = None
            self.gateway = self.DEFAULT_GATEWAY
            _log.info('Shard ID %s session has been invalidated.', self.shard_id)
            await self.close(code=1000)
            raise ReconnectWebSocket(self.shard_id, resume=False)

        _log.warning('Unknown OP code %s.', op)
        return

    if event == 'READY':
        self.sequence = msg['s']
        self.session_id = data['session_id']
        self.gateway = yarl.URL(data['resume_gateway_url'])
        _log.info('Shard ID %s has connected to Gateway (Session ID: %s).', self.shard_id, self.session_id)

    elif event == 'RESUMED':
        # pass back the shard ID to the resumed handler
        data['__shard_id__'] = self.shard_id
        _log.info('Shard ID %s has successfully RESUMED session %s.', self.shard_id, self.session_id)

    try:
        func = self._discord_parsers[event]
    except KeyError:
        _log.debug('Unknown event %s.', event)
    else:
        func(data)

    # remove the dispatched listeners
    removed = []
    for index, entry in enumerate(self._dispatch_listeners):
        if entry.event != event:
            continue

        future = entry.future
        if future.cancelled():
            removed.append(index)
            continue

        try:
            valid = entry.predicate(data)
        except Exception as exc:
            future.set_exception(exc)
            removed.append(index)
        else:
            if valid:
                ret = data if entry.result is None else entry.result(data)
                future.set_result(ret)
                removed.append(index)

    for index in reversed(removed):
        del self._dispatch_listeners[index]

def _can_handle_close(self) -> bool:
    code = self._close_code or self.socket.close_code
    return code not in (1000, 4004, 4010, 4011, 4012, 4013, 4014)

async def send_as_json(self, data: Any) -> None:
    try:
        await self.send(utils._to_json(data))
    except RuntimeError as exc:
        if not self._can_handle_close():
            raise ConnectionClosed(self.socket, shard_id=self.shard_id) from exc

async def ws_connect(self, url: str, *, compress: int = 0) -> aiohttp.ClientWebSocketResponse:
    kwargs = {
        'proxy_auth': self.proxy_auth,
        'proxy': self.proxy,
        'max_msg_size': 0,
        'timeout': 30.0,
        'autoclose': False,
        'headers': {
            'User-Agent': self.user_agent,
        },
        'compress': compress,
    }

    return await self.__session.ws_connect(url, **kwargs)

def run(self) -> None:
    while not self._stop_ev.wait(self.interval):
        if self._last_recv + self.heartbeat_timeout < time.perf_counter():
            _log.warning("Shard ID %s has stopped responding to the gateway. Closing and restarting.", self.shard_id)
            coro = self.ws.close(4000)
            f = asyncio.run_coroutine_threadsafe(coro, loop=self.ws.loop)

            try:
                f.result()
            except Exception:
                _log.exception('An error occurred while stopping the gateway. Ignoring.')
            finally:
                self.stop()
                return

        data = self.get_payload()
        _log.debug(self.msg, self.shard_id, data['d'])
        coro = self.ws.send_heartbeat(data)
        f = asyncio.run_coroutine_threadsafe(coro, loop=self.ws.loop)
        try:
            # block until sending is complete
            total = 0
            while True:
                try:
                    f.result(10)
                    break
                except concurrent.futures.TimeoutError:
                    total += 10
                    try:
                        frame = sys._current_frames()[self._main_thread_id]
                    except KeyError:
                        msg = self.block_msg
                    else:
                        stack = ''.join(traceback.format_stack(frame))
                        msg = f'{self.block_msg}\nLoop thread traceback (most recent call last):\n{stack}'
                    _log.warning(msg, self.shard_id, total)

        except Exception:
            self.stop()
        else:
            self._last_send = time.perf_counter()

def get_payload(self) -> Dict[str, Any]:
    return {
        'op': self.ws.HEARTBEAT,
        'd': self.ws.sequence,
    }

def get_payload(self) -> Dict[str, Any]:
    return {
        'op': self.ws.HEARTBEAT,
        'd': int(time.time() * 1000),
    }

async def send_heartbeat(self, data: Any) -> None:
    # This bypasses the rate limit handling code since it has a higher priority
    try:
        await self.socket.send_str(utils._to_json(data))
    except RuntimeError as exc:
        if not self._can_handle_close():
            raise ConnectionClosed(self.socket, shard_id=self.shard_id) from exc

def average_latency(self) -> float:
    """:class:`float`: Average of last 20 HEARTBEAT latencies."""
    heartbeat = self._keep_alive
    if heartbeat is None or not heartbeat.recent_ack_latencies:
        return float('inf')

    return sum(heartbeat.recent_ack_latencies) / len(heartbeat.recent_ack_latencies)

def latency(self) -> float:
    """:class:`float`: Measures latency between a HEARTBEAT and a HEARTBEAT_ACK in seconds for this shard."""
    return self._parent.ws.latency

def latency(self) -> float:
    """:class:`float`: Measures latency between a HEARTBEAT and a HEARTBEAT_ACK in seconds.

    This operates similarly to :meth:`Client.latency` except it uses the average
    latency of every shard's latency. To get a list of shard latency, check the
    :attr:`latencies` property. Returns ``nan`` if there are no shards ready.
    """
    if not self.__shards:
        return float('nan')
    return sum(latency for _, latency in self.latencies) / len(self.__shards)

def ack(self) -> None:
    ack_time = time.perf_counter()
    self._last_ack = ack_time
    self.latency = ack_time - self._last_send
    if self.latency > 10:
        _log.warning(self.behind_msg, self.shard_id, self.latency)

