def __init__(self, values: Tuple[Any, ...]) -> None:
    first = type(values[0])
    if first is int:
        opt_type = AppCommandOptionType.integer
    elif first is float:
        opt_type = AppCommandOptionType.number
    elif first is str:
        opt_type = AppCommandOptionType.string
    else:
