    msg = ctx.message

    if ctx.guild:

        def resolve_member(id: int) -> str:
            m = _utils_get(msg.mentions, id=id) or ctx.guild.get_member(id)  # type: ignore
            return f'@{m.display_name if self.use_nicknames else m.name}' if m else '@deleted-user'

