    v = self.value
    if v == -1:
        return 'all'
    elif v < 10:
        return 'guild'
    elif v < 20:
        return 'channel'
    elif v < 30:
        return 'user'
    elif v < 40:
        return 'role'
    elif v < 50:
        return 'invite'
    elif v < 60:
        return 'webhook'
    elif v < 70:
        return 'emoji'
    elif v == 73:
        return 'channel'
    elif v < 80:
        return 'message'
    elif v < 83:
